use vstd::prelude::*;

verus! {
    fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
        requires
            s1.len() == s2.len() && s2.len() == s3.len(),
            s1.len() <= i32::MAX as usize,
        ensures
            res.len() == 3 * s1.len(),
            forall |i: nat| (i < s1.len() as nat) ==> 
                res[3 * i as usize] == s1[i as usize] &&
                res[3 * i as usize + 1] == s2[i as usize] &&
                res[3 * i as usize + 2] == s3[i as usize],
    {
        let n = s1.len() as nat;
        let mut res: Vec<i32> = Vec::new();
        res.reserve(3 * n as usize); // Reserve space for 3n elements

        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                res.len() == 3 * i as usize,
                forall |j: nat| (j < i) ==> 
                    res[3 * j as usize] == s1[j as usize] &&
                    res[3 * j as usize + 1] == s2[j as usize] &&
                    res[3 * j as usize + 2] == s3[j as usize],
            decreases n - i,
        {
            res.push(s1[i as usize]);
            res.push(s2[i as usize]);
            res.push(s3[i as usize]);
            i = i + 1;
        }
        res
    }
}
